# ============================================================
# SPAIN CPI: HISTORICAL TABLES AND MODEL ENSEMBLES
# Uses files generated by the preceding extended analysis.
# Run from the RStudio project root.
# ============================================================

RESULTS_DIR <- file.path("results", "working")
dir.create(RESULTS_DIR, recursive = TRUE, showWarnings = FALSE)

paquetes <- c("readr", "dplyr", "tidyr", "lubridate", "tibble")
no_instalados <- paquetes[!vapply(paquetes, requireNamespace, logical(1), quietly = TRUE)]
if (length(no_instalados) > 0) {
  stop("Missing packages: ", paste(no_instalados, collapse = ", "),
       ". Install them with install.packages() and run the script again.")
}

library(readr)
library(dplyr)
library(tidyr)
library(lubridate)
library(tibble)

archivo_bt <- file.path(RESULTS_DIR, "ipc_modelos_ampliados_backtest.csv")
archivo_actual <- file.path(RESULTS_DIR, "ipc_prevision_final_modelos_comparados.csv")
if (!file.exists(archivo_bt)) stop("Missing ", archivo_bt, " in the working directory.")
if (!file.exists(archivo_actual)) stop("Missing ", archivo_actual, ". Run the extended comparison script first.")

bt <- read_csv(archivo_bt, show_col_types = FALSE) %>%
  mutate(
    fecha_origen = as.Date(fecha_origen),
    fecha_objetivo = as.Date(fecha_objetivo),
    horizonte = as.integer(horizonte),
    prediccion = as.numeric(prediccion),
    real = as.numeric(real),
    error = real - prediccion
  ) %>%
  filter(!is.na(fecha_origen), !is.na(fecha_objetivo),
         is.finite(prediccion), is.finite(real))

# -----------------------------------------------------------------
# 1) ENSEMBLE COMPARISON. No bias correction is applied.
#    Weights are prespecified rather than optimized on the evaluation sample.
# -----------------------------------------------------------------
modelos_base <- c("ARIMA", "Naive", "Random Forest")
faltan <- setdiff(modelos_base, unique(bt$modelo))
if (length(faltan) > 0) stop("Missing models in the backtest: ", paste(faltan, collapse = ", "))

real_por_objetivo <- bt %>%
  group_by(fecha_origen, fecha_objetivo, horizonte) %>%
  summarise(real = first(real), .groups = "drop")

wide <- bt %>%
  filter(modelo %in% modelos_base) %>%
  select(fecha_origen, fecha_objetivo, horizonte, modelo, prediccion) %>%
  pivot_wider(names_from = modelo, values_from = prediccion) %>%
  left_join(real_por_objetivo, by = c("fecha_origen", "fecha_objetivo", "horizonte")) %>%
  filter(if_all(all_of(modelos_base), ~ is.finite(.x)), is.finite(real)) %>%
  mutate(
    `ARIMA + Naive (50/50)` = 0.50 * ARIMA + 0.50 * Naive,
    `ARIMA + Naive (75/25)` = 0.75 * ARIMA + 0.25 * Naive,
    `ARIMA + Random Forest (75/25)` = 0.75 * ARIMA + 0.25 * `Random Forest`,
    `Mean of ARIMA, Naive, and Random Forest` = (ARIMA + Naive + `Random Forest`) / 3
  )

candidatos <- c("ARIMA", "Naive", "Random Forest", "ARIMA + Naive (50/50)",
                "ARIMA + Naive (75/25)", "ARIMA + Random Forest (75/25)",
                "Mean of ARIMA, Naive, and Random Forest")

long <- wide %>%
  select(fecha_origen, fecha_objetivo, horizonte, real, all_of(candidatos)) %>%
  pivot_longer(cols = all_of(candidatos), names_to = "modelo", values_to = "prediccion") %>%
  mutate(error = real - prediccion, error_abs = abs(error))

metricas_combinadas <- long %>%
  group_by(modelo) %>%
  summarise(
    MAE = mean(error_abs, na.rm = TRUE),
    RMSE = sqrt(mean(error^2, na.rm = TRUE)),
    observaciones = n(),
    .groups = "drop"
  ) %>% arrange(MAE)

metricas_h <- long %>%
  group_by(modelo, horizonte) %>%
  summarise(
    MAE = mean(error_abs, na.rm = TRUE),
    RMSE = sqrt(mean(error^2, na.rm = TRUE)),
    observaciones = n(),
    .groups = "drop"
  ) %>% arrange(horizonte, MAE)

write_csv(metricas_combinadas, file.path(RESULTS_DIR, "ipc_comparacion_modelos_combinados.csv"))
write_csv(metricas_h, file.path(RESULTS_DIR, "ipc_comparacion_combinados_por_horizonte.csv"))
cat("\n================ INDIVIDUAL MODELS AND ENSEMBLES ================\n")
print(metricas_combinadas %>% mutate(across(c(MAE, RMSE), ~ round(.x, 3))), n = Inf)
cat("\n================ RESULTS BY FORECAST HORIZON ================\n")
print(metricas_h %>% mutate(across(c(MAE, RMSE), ~ round(.x, 3))), n = Inf)

# -----------------------------------------------------------------
# 2) OCT–DEC HISTORY: a readable table without hidden columns.
#    Shows forecasts issued in September of each available year.
# -----------------------------------------------------------------
mes_nombre <- function(x) recode(as.character(x), `10` = "October", `11` = "November", `12` = "December")

oto <- bt %>%
  mutate(
    anio_origen = year(fecha_origen),
    mes_origen = month(fecha_origen),
    anio_objetivo = year(fecha_objetivo),
    mes_objetivo = month(fecha_objetivo)
  ) %>%
  filter(mes_origen == 9L, anio_objetivo == anio_origen,
         mes_objetivo %in% c(10L, 11L, 12L),
         modelo %in% c("ARIMA", "Naive", "Random Forest", "ETS", "Naive with Drift", "Theta")) %>%
  mutate(
    mes = mes_nombre(mes_objetivo),
    error = real - prediccion,
    error_abs = abs(error)
  ) %>%
  transmute(
    anio = anio_origen, mes, horizonte, modelo,
    IPC_real = real, prediccion = prediccion,
    error = error, error_abs = error_abs
  ) %>%
  arrange(anio, horizonte, match(modelo, c("ARIMA", "Naive", "Random Forest", "ETS", "Naive with Drift", "Theta")))

write_csv(oto, file.path(RESULTS_DIR, "ipc_previsiones_historicas_otono_resumen.csv"))
cat("\n================ HISTORICAL FORECASTS ISSUED IN SEPTEMBER ================\n")
if (nrow(oto) > 0) {
  print(oto %>% mutate(across(c(IPC_real, prediccion, error, error_abs), ~ round(.x, 3))), n = Inf, width = Inf)
  cat("\nYears available in the October–December comparison:", n_distinct(oto$anio), "\n")
} else {
  cat("No October–December observations are available for September origins.\n")
}

# Autumn metrics use only years with available observations.
metricas_oto <- oto %>%
  group_by(modelo, horizonte, mes) %>%
  summarise(
    n = n(),
    MAE = mean(error_abs, na.rm = TRUE),
    RMSE = sqrt(mean(error^2, na.rm = TRUE)),
    .groups = "drop"
  ) %>% arrange(horizonte, MAE)
write_csv(metricas_oto, file.path(RESULTS_DIR, "ipc_metricas_otono_modelos_claras.csv"))
cat("\n================ OCTOBER–DECEMBER METRICS BY HORIZON ================\n")
print(metricas_oto %>% mutate(across(c(MAE, RMSE), ~ round(.x, 3))), n = Inf, width = Inf)

# -----------------------------------------------------------------
# 3) OCT–DEC 2026 ENSEMBLES based on the forecasts already calculated.
# -----------------------------------------------------------------
actual <- read_csv(archivo_actual, show_col_types = FALSE) %>%
  mutate(fecha_objetivo = as.Date(fecha_objetivo),
         prediccion_bruta = as.numeric(prediccion_bruta)) %>%
  filter(modelo %in% modelos_base, is.finite(prediccion_bruta)) %>%
  select(fecha_objetivo, horizonte, modelo, prediccion_bruta) %>%
  pivot_wider(names_from = modelo, values_from = prediccion_bruta) %>%
  arrange(fecha_objetivo)

if (all(modelos_base %in% names(actual))) {
  actual <- actual %>%
    mutate(
      `ARIMA + Naive (50/50)` = 0.50 * ARIMA + 0.50 * Naive,
      `ARIMA + Naive (75/25)` = 0.75 * ARIMA + 0.25 * Naive,
      `ARIMA + Random Forest (75/25)` = 0.75 * ARIMA + 0.25 * `Random Forest`,
      `Mean of ARIMA, Naive, and Random Forest` = (ARIMA + Naive + `Random Forest`) / 3
    ) %>%
    select(fecha_objetivo, horizonte, all_of(candidatos))
  write_csv(actual, file.path(RESULTS_DIR, "ipc_prevision_actual_combinaciones.csv"))
  cat("\n================ CURRENT ENSEMBLE FORECASTS WITHOUT BIAS CORRECTION ================\n")
  print(actual %>% mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf, width = Inf)
} else {
  cat("\nNot all current ensembles could be calculated because at least one model is unavailable.\n")
}

cat("\nGenerated files:\n",
    "- ipc_comparacion_modelos_combinados.csv\n",
    "- ipc_comparacion_combinados_por_horizonte.csv\n",
    "- ipc_previsiones_historicas_otono_resumen.csv\n",
    "- ipc_metricas_otono_modelos_claras.csv\n",
    "- ipc_prevision_actual_combinaciones.csv\n", sep = "")
cat("\nEnsemble analysis complete.\n")
